const{contextBridge:contextBridge,ipcRenderer:ipcRenderer,shell:shell}=require("electron");contextBridge.exposeInMainWorld("api",{getAppVersion:()=>{try{return ipcRenderer.invoke("get-app-version")}catch(e){return null}},openWebsite:e=>{"string"==typeof e&&e.startsWith("http")&&shell.openExternal(e)}});